//! Generic synchronous HTTP adapter. Application DTO conversion is generated by Lift.
use axum::{
    body::{to_bytes, Body},
    http::{Request as HttpRequest, StatusCode},
    response::Response as HttpResponse,
    routing::{MethodFilter, MethodRouter},
    Router,
};
use std::sync::{Arc, Mutex};
use tokio::sync::Semaphore;

pub struct Request {
    pub method: String,
    pub path: String,
    pub query: String,
    pub body: String,
}
pub struct Response {
    pub status: i64,
    pub body: String,
}
#[derive(Clone, Copy)]
enum Handler { Plain(fn(Request) -> Response), Database(fn(Request, &lift_db::api::DbPool) -> Response) }
struct Route {
    method: String,
    path: String,
    handler: Handler,
}
static ROUTES: Mutex<Vec<Route>> = Mutex::new(Vec::new());
pub fn available() {}
pub fn is_blank(value: &str) -> bool {
    value.trim().is_empty()
}
pub fn register_route(method: &str, path: &str, handler: fn(Request) -> Response) {
    ROUTES.lock().expect("route registry poisoned").push(Route {
        method: method.into(),
        path: path.into(),
        handler: Handler::Plain(handler),
    });
}
pub fn register_db_route(method: &str, path: &str, handler: fn(Request, &lift_db::api::DbPool) -> Response) {
    ROUTES.lock().expect("route registry poisoned").push(Route { method: method.into(), path: path.into(), handler: Handler::Database(handler) });
}
pub fn serve(address: &str, max_body_bytes: i64) -> Result<(), String> {
    serve_inner(address,max_body_bytes,None)
}
pub fn serve_with_pool(address: &str, max_body_bytes: i64, pool: lift_db::api::DbPool) -> Result<(), String> {
    serve_inner(address,max_body_bytes,Some(pool))
}
fn serve_inner(address: &str, max_body_bytes: i64, pool: Option<lift_db::api::DbPool>) -> Result<(), String> {
    if !(1..=1_048_576).contains(&max_body_bytes) {
        return Err("body limit must be between 1 and 1048576 bytes".into());
    }
    let address = std::env::var("LIFT_HTTP_ADDR").unwrap_or_else(|_| address.into());
    let address: std::net::SocketAddr = address
        .parse()
        .map_err(|e| format!("invalid HTTP address: {e}"))?;
    let routes = std::mem::take(&mut *ROUTES.lock().map_err(|_| "route registry poisoned")?);
    if routes.is_empty() {
        return Err("at least one static route is required".into());
    }
    if pool.is_none() && routes.iter().any(|r| matches!(r.handler,Handler::Database(_))) {
        return Err("a database handler requires http.serve(address, body_limit, pool)".into());
    }
    let pool = pool.map(Arc::new);
    let slots = Arc::new(Semaphore::new(8));
    let mut app = Router::new();
    for route in routes {
        let filter = match route.method.as_str() {
            "GET" => MethodFilter::GET,
            "POST" => MethodFilter::POST,
            "PUT" => MethodFilter::PUT,
            "DELETE" => MethodFilter::DELETE,
            "PATCH" => MethodFilter::PATCH,
            _ => return Err("unsupported HTTP method".into()),
        };
        let handler = route.handler;
        let slots = slots.clone();
        let pool = pool.clone();
        app = app.route(
            &route.path,
            MethodRouter::new().on(filter, move |request: HttpRequest<Body>| {
                let slots = slots.clone();
                let pool = pool.clone();
                async move { dispatch(request, handler, max_body_bytes as usize, slots, pool).await }
            }),
        );
    }
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(2)
        .enable_all()
        .build()
        .map_err(|e| e.to_string())?;
    runtime.block_on(async move {
        let listener = tokio::net::TcpListener::bind(address)
            .await
            .map_err(|e| format!("could not bind {address}: {e}"))?;
        axum::serve(listener, app)
            .await
            .map_err(|e| format!("HTTP server failed: {e}"))
    })
}
async fn dispatch(
    request: HttpRequest<Body>,
    handler: Handler,
    limit: usize,
    slots: Arc<Semaphore>,
    pool: Option<Arc<lift_db::api::DbPool>>,
) -> HttpResponse<Body> {
    let (parts, body) = request.into_parts();
    let bytes = match to_bytes(body, limit).await {
        Ok(b) => b,
        Err(_) => return response(413, "request body exceeds limit"),
    };
    let body = match String::from_utf8(bytes.to_vec()) {
        Ok(s) => s,
        Err(_) => return response(400, "request body must be valid UTF-8"),
    };
    let permit = match slots.try_acquire_owned() {
        Ok(p) => p,
        Err(_) => return response(503, "service is busy"),
    };
    let request = Request {
        method: parts.method.to_string(),
        path: parts.uri.path().into(),
        query: parts.uri.query().unwrap_or_default().into(),
        body,
    };
    match tokio::task::spawn_blocking(move || {
        let _permit = permit;
        match handler {
            Handler::Plain(handler) => handler(request),
            Handler::Database(handler) => handler(request, pool.as_deref().expect("database routes require a server-owned pool")),
        }
    })
    .await
    {
        Ok(output) if (200..=599).contains(&output.status) => {
            response(output.status as u16, &output.body)
        }
        Ok(_) => response(500, "invalid response status"),
        Err(_) => response(500, "request handler failed"),
    }
}
fn response(status: u16, body: &str) -> HttpResponse<Body> {
    HttpResponse::builder()
        .status(StatusCode::from_u16(status).expect("validated status"))
        .header("content-type", "text/plain; charset=utf-8")
        .body(Body::from(body.to_owned()))
        .expect("valid text response")
}
